WITH base AS (SELECT *, TRIM(browser) clean_browser, COALESCE(country, 'N/A') resolved_country FROM sessions WHERE started_at >= TIMESTAMP '2023-09-08 20:00:00' AND device = 'desktop'), with_prev AS (SELECT *, LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) AS prev_started_at FROM base), gaps AS (SELECT *, CASE WHEN prev_started_at IS NULL OR started_at > prev_started_at + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_session FROM with_prev), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT CASE WHEN is_new_session >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS is_new_session_tier, ROUND(SUM(is_new_session) / NULLIF(COUNT(CASE WHEN device = 'tablet' THEN 1 END), 0), 2) AS is_new_session_per_tablet, MIN(started_at) AS started_at, SORT_ARRAY(COLLECT_SET(country)) AS country_list, COUNT(CASE WHEN country = 'DE' THEN 1 END) AS de_count, GROUPING(CASE WHEN is_new_session >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END) AS gid FROM islands GROUP BY ROLLUP (CASE WHEN is_new_session >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY de_count DESC
